async (state, model) => {
  const dataSource = state.dataSource || 'default_dataset.csv';
  const prompt = `Load and validate data from: ${dataSource}. Provide a summary of the data structure and quality.`;

  const result = await model.invoke([{ role: 'user', content: prompt }]);

  return {
    analysisResults: { dataLoaded: true, summary: result.content.toString() },
    messages: [{ role: 'assistant', content: `Data Loaded: ${result.content}` }]
  };
}

async (state, model) => {
  const dataSummary = state.analysisResults.summary || 'No data summary available';
  const prompt = `Use the data_analysis and statistical_analysis skills to analyze:\n${dataSummary}\n\nProvide key metrics, patterns, and statistical insights.`;

  const result = await model.invoke([{ role: 'user', content: prompt }]);

  return {
    analysisResults: {
      ...state.analysisResults,
      analysis: result.content.toString(),
      timestamp: new Date().toISOString()
    },
    messages: [{ role: 'assistant', content: `Analysis Complete: ${result.content}` }]
  };
}

async (state, model) => {
  const analysis = state.analysisResults.analysis || 'No analysis available';
  const prompt = `Use the visualization skill to create charts and graphs for:\n${analysis}\n\nRecommend appropriate visualization types and describe them.`;

  const result = await model.invoke([{ role: 'user', content: prompt }]);

  return {
    visualizations: [
      'bar_chart.png',
      'line_graph.png',
      'scatter_plot.png'
    ],
    messages: [{ role: 'assistant', content: `Visualizations Created: ${result.content}` }]
  };
}

async (state, model) => {
  const context = `
Data Source: ${state.dataSource}
Analysis Results: ${JSON.stringify(state.analysisResults)}
Visualizations: ${state.visualizations.join(', ')}
`;

  const prompt = `Generate a comprehensive data analysis report with:
1. Executive Summary
2. Key Findings
3. Detailed Analysis
4. Visualizations Reference
5. Recommendations

Context:${context}`;

  const result = await model.invoke([{ role: 'user', content: prompt }]);

  return {
    report: result.content.toString(),
    messages: [{ role: 'assistant', content: `Report Generated: ${result.content}` }]
  };
}
